languages.python:
rest = path.replace("\\", "/")
drive = ""
if len(rest) >= 2 and rest[1] == ":" and ("A" <= rest[0] <= "Z" or "a" <= rest[0] <= "z"):
    drive = rest[:2]
    rest = rest[2:]
absolute = rest.startswith("/")
parts = []
for part in rest.split("/"):
    if part in ("", "."):
        continue
    if part == "..":
        if parts and parts[-1] != "..":
            parts.pop()
        elif not absolute:
            parts.append("..")
    else:
        parts.append(part)
joined = ("/" if absolute else "") + "/".join(parts)
return drive + (joined or ".")

